from datetime import datetime

token = apis.spotify.login(username='erikabail@gmail.com', password=[a['password'] for a in apis.supervisor.show_account_passwords() if a['account_name']=='spotify'][0])['access_token']

# Re-fetch ids quickly from prior counts by calling the library endpoints and union them.

def fetch_song_ids_from_endpoint(fetch_fn):
    song_ids=set(); page_index=0; page_limit=20
    while True:
        resp = fetch_fn(access_token=token, page_index=page_index, page_limit=page_limit)
        if not resp:
            break
        for r in resp:
            # song ids are either in root or within playlist/album records
            if 'song_id' in r:
                song_ids.add(r['song_id'])
            elif 'song_ids' in r:
                for sid in r.get('song_ids', []):
                    song_ids.add(sid)
        page_index += 1
    return song_ids

song_ids = fetch_song_ids_from_endpoint(lambda access_token, page_index, page_limit: apis.spotify.show_song_library(access_token=access_token, page_index=page_index, page_limit=page_limit))
album_song_ids = fetch_song_ids_from_endpoint(lambda access_token, page_index, page_limit: apis.spotify.show_album_library(access_token=access_token, page_index=page_index, page_limit=page_limit))
playlist_song_ids = fetch_song_ids_from_endpoint(lambda access_token, page_index, page_limit: apis.spotify.show_playlist_library(access_token=access_token, page_index=page_index, page_limit=page_limit))

union_ids = sorted(list(song_ids | album_song_ids | playlist_song_ids))
print('counts song_library', len(song_ids), 'album_song_ids', len(album_song_ids), 'playlist_song_ids', len(playlist_song_ids))
print('union unique song ids', len(union_ids))
print('union sample ids', union_ids[:20])

songs_info=[]
for i, sid in enumerate(union_ids, start=1):
    s = apis.spotify.show_song(song_id=sid)
    rd = s.get('release_date')
    songs_info.append({
        'song_id': sid,
        'title': s.get('title'),
        'album_title': s.get('album_title'),
        'release_date': rd
    })
    if i<=5 or i==len(union_ids):
        print('checked', i, 'song_id', sid, 'title', s.get('title'), 'release_date', rd)

# Determine oldest by release_date

def parse_rd(rd):
    if rd is None:
        return None
    try:
        return datetime.fromisoformat(rd.replace('Z',''))
    except Exception:
        try:
            return datetime.strptime(rd[:10], '%Y-%m-%d')
        except Exception:
            return None

for rec in songs_info:
    rec['release_dt']=parse_rd(rec['release_date'])

valid = [r for r in songs_info if r['release_dt'] is not None]
print('songs with valid release_date', len(valid), 'out of', len(songs_info))

oldest = min(valid, key=lambda r: r['release_dt'])
# In case of tie, collect all with same dt
oldest_dt = oldest['release_dt']
tied = sorted([r for r in valid if r['release_dt']==oldest_dt], key=lambda r: r['title'])
print('oldest release_dt', oldest_dt)
print('tied count', len(tied))
for r in tied:
    print(' -', r['title'], 'from', r.get('album_title'), 'release_date', r['release_date'], 'song_id', r['song_id'])

print('OLDLST_TITLE', tied[0]['title'])
